<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{PurchaseRequisition,RequestForQuotation,Supplier};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class RfqController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.rfqs.index',['rows'=>RequestForQuotation::with(['requisition','suppliers'])->where('property_id',$p)->latest()->paginate(30),'requisitions'=>PurchaseRequisition::where('property_id',$p)->where('status','approved')->get(),'suppliers'=>Supplier::where('property_id',$p)->where('is_active',1)->get()]);}public function store(Request $r){$d=$r->validate(['purchase_requisition_id'=>'nullable|integer','deadline_at'=>'nullable|date','supplier_ids'=>'required|array|min:1','supplier_ids.*'=>'integer','notes'=>'nullable']);DB::transaction(function()use($d){$rfq=RequestForQuotation::create(['property_id'=>auth()->user()->property_id,'purchase_requisition_id'=>$d['purchase_requisition_id']??null,'number'=>'RFQ-'.now()->format('Ymd-His').'-'.random_int(10,99),'deadline_at'=>$d['deadline_at']??null,'status'=>'sent','notes'=>$d['notes']??null,'created_by'=>auth()->id()]);$rfq->suppliers()->sync($d['supplier_ids']);});return back()->with('success','RFQ created and suppliers attached.');}public function quote(Request $r,RequestForQuotation $rfq,Supplier $supplier){abort_unless($rfq->property_id===auth()->user()->property_id&&$supplier->property_id===auth()->user()->property_id,403);$d=$r->validate(['quoted_total'=>'required|numeric|min:0','quotation_reference'=>'nullable|max:100','quotation_date'=>'nullable|date','notes'=>'nullable']);$rfq->suppliers()->updateExistingPivot($supplier->id,$d);return back()->with('success','Supplier quotation recorded.');}public function award(RequestForQuotation $rfq,Supplier $supplier){abort_unless($rfq->property_id===auth()->user()->property_id&&$supplier->property_id===auth()->user()->property_id,403);DB::transaction(function()use($rfq,$supplier){DB::table('rfq_suppliers')->where('request_for_quotation_id',$rfq->id)->update(['is_awarded'=>false]);$rfq->suppliers()->updateExistingPivot($supplier->id,['is_awarded'=>true]);$rfq->update(['status'=>'awarded']);});return back()->with('success','RFQ awarded.');}}
